from ute_core.exception import CoreException


class TsharkError(CoreException):
    """Exception  is raised if tshark error."""


class TsharkExecutionError(TsharkError):
    """Exception  is raised if shell command return code is not zero."""


class GettingPacketsNumberIsImpossible(TsharkError):
    """Exception is raised if is not possible to get packets number."""


class WaitingForPacketTimeout(TsharkError):
    """Exception is raised if waiting time expires."""


class ProcessIsAlreadyRunning(TsharkError):
    """Exception is raised if it is try of overwrite process."""


class StartProcessError(TsharkError):
    """Exception is raised if process is not able to start."""


class StopProcessError(TsharkError):
    """Exception is raised if process is not able to stop."""


class CapturingPacketsError(TsharkError):
    """Exception is raised if the number of packets captured is not equal to the given packet number. """


class MessageNotFound(TsharkError):
    """Exception is raised if the message is not present in the pcap file to be read."""


class FieldOptionNullError(TsharkError):
    """Exception is raised if the field option parameter is empty"""
